"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/badge.css";
import { X } from "@phosphor-icons/react";
import type { ComponentPropsWithRef, ReactNode } from "react";
import { cn } from "../../lib/cn";

export type BadgeProps = ComponentPropsWithRef<"span"> & {
  variant?: "neutral" | "strong" | "outline" | "success" | "warning" | "danger";
  leadingIcon?: ReactNode;
  removable?: boolean;
  onRemove?: () => void;
  removeLabel?: string;
};

export function Badge({
  className,
  variant = "neutral",
  leadingIcon,
  removable,
  onRemove,
  removeLabel = "Remove",
  children,
  ...props
}: BadgeProps) {
  return (
    <span className={cn("whatiuse-badge", `whatiuse-badge--${variant}`, className)} {...props}>
      {leadingIcon && <span className="whatiuse-badge__icon" aria-hidden="true">{leadingIcon}</span>}
      <span className="whatiuse-badge__label">{children}</span>
      {removable && (
        <button type="button" className="whatiuse-badge__remove" aria-label={removeLabel} onClick={onRemove}>
          <X aria-hidden="true" />
        </button>
      )}
    </span>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-badge {
  display: inline-flex;
  min-width: 0;
  height: 21px;
  align-items: center;
  gap: 4px;
  padding: 0 6px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: color-mix(in oklch, var(--whatiuse-bg-subtle) 88%, transparent);
  color: var(--whatiuse-fg-muted);
  font-size: 11.5px;
  font-weight: 550;
  line-height: 1;
  letter-spacing: -0.006em;
  white-space: nowrap;
}

.whatiuse-badge__icon,
.whatiuse-badge__icon svg { width: 11px; height: 11px; flex: 0 0 auto; }

.whatiuse-badge__label { overflow: hidden; text-overflow: ellipsis; }

.whatiuse-badge__remove {
  position: relative;
  display: grid;
  width: 17px;
  height: 17px;
  margin-right: -4px;
  place-items: center;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: currentColor;
  cursor: pointer;
}

.whatiuse-badge__remove::after {
  position: absolute;
  inset: -4px;
  content: "";
}

.whatiuse-badge__remove svg { width: 11px; height: 11px; }

.whatiuse-badge__remove:focus-visible { outline: 1.5px solid currentColor; outline-offset: -2px; }

@media (hover: hover) and (pointer: fine) {
.whatiuse-badge__remove:hover { background: var(--whatiuse-hover); color: var(--whatiuse-ink); }
}

.whatiuse-badge__remove { transition: color var(--whatiuse-hover-duration), background-color var(--whatiuse-hover-duration), transform var(--whatiuse-press-duration) var(--whatiuse-ease-out); }

.whatiuse-badge__remove:active { transform: scale(.96); }

@media (prefers-reduced-motion: reduce) {
.whatiuse-badge__remove:active { transform: none; }
}
}
